function validate([nums, k, queries]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each nums[i] is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 5) return 'k is between 1 and 5.';
  if (queries.length < 1 || queries.length > 20000) return 'queries needs 1 to 2 * 10^4 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 4) return 'Each query is [index, value, start, x].';
    const [index, value, start, x] = query;
    if (!Number.isInteger(index) || index < 0 || index >= n) return 'Each index must be a position in nums.';
    if (!Number.isInteger(value) || value < 1 || value > 1e9) return 'Each value is an integer from 1 to 10^9.';
    if (!Number.isInteger(start) || start < 0 || start >= n) return 'Each start must be a position in nums.';
    if (!Number.isInteger(x) || x < 0 || x >= k) return 'Each x is between 0 and k - 1.';
  }
  return null;
}

