function resultArray(nums, k, queries) {
  const n = nums.length;
  const tree = new Array(4 * n);
  const leaf = (value) => {
    const counts = new Array(k).fill(0);
    counts[value % k] = 1;
    return { product: value % k, counts };
  };
  const combine = (left, right) => {
    const counts = [...left.counts];
    for (let r = 0; r < k; r++) {
      counts[(left.product * r) % k] += right.counts[r];
    }
    return { product: (left.product * right.product) % k, counts };
  };
  const build = (node, low, high) => {
    if (low === high) {
      tree[node] = leaf(nums[low]);
      return;
    }
    const mid = (low + high) >> 1;
    build(2 * node, low, mid);
    build(2 * node + 1, mid + 1, high);
    tree[node] = combine(tree[2 * node], tree[2 * node + 1]);
  };
  const update = (node, low, high, index, value) => {
    if (low === high) {
      tree[node] = leaf(value);
      return;
    }
    const mid = (low + high) >> 1;
    if (index <= mid) {
      update(2 * node, low, mid, index, value);
    } else {
      update(2 * node + 1, mid + 1, high, index, value);
    }
    tree[node] = combine(tree[2 * node], tree[2 * node + 1]);
  };
  const suffix = (node, low, high, start) => {
    if (low >= start) {
      return tree[node];
    }
    const mid = (low + high) >> 1;
    if (start > mid) {
      return suffix(2 * node + 1, mid + 1, high, start);
    }
    return combine(suffix(2 * node, low, mid, start), tree[2 * node + 1]);
  };
  build(1, 0, n - 1);
  const result = [];
  for (const [index, value, start, x] of queries) {
    update(1, 0, n - 1, index, value);
    result.push(suffix(1, 0, n - 1, start).counts[x]);
  }
  return result;
}

