function resultArray(nums, k, queries) {
  // Apply each update to a copy, then multiply from start to the end, counting the matching remainders.
  const arr = nums.slice();
  return queries.map(([index, value, start, x]) => {
    arr[index] = value;
    let product = 1;
    let ways = 0;
    for (let end = start; end < arr.length; end++) {
      product = (product * (arr[end] % k)) % k;
      if (product === x) ways++;
    }
    return ways;
  });
}

