function generate(rand, size) {
  const large = size === 'large';
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const n = large ? 2000 : pick(1, 6);
  const k = pick(1, 5);
  // Values coprime to k keep products away from 0, so every remainder shows up.
  const coprime = k > 1 && rand() < 0.5;
  const number = () => {
    for (;;) {
      const v = large ? pick(1, 1e9) : pick(1, 12);
      if (!coprime || gcd(v, k) === 1) return v;
    }
  };
  const nums = Array.from({ length: n }, number);
  const queries = Array.from({ length: large ? 2000 : pick(1, 5) }, () => [pick(0, n - 1), number(), pick(0, n - 1), pick(0, k - 1)]);
  return [nums, k, queries];
}
